-- Empty staging databases only. Fictional fixture rows are inserted separately.
CREATE TABLE projects(id INT PRIMARY KEY,name VARCHAR(150) NOT NULL,status VARCHAR(16) NOT NULL) ENGINE=InnoDB;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(100) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,full_name VARCHAR(100) NOT NULL,user_type VARCHAR(20) NOT NULL,role VARCHAR(30) NOT NULL,status VARCHAR(16) NOT NULL,is_active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE suite_instance_binding(singleton TINYINT PRIMARY KEY,instance_id BIGINT NOT NULL,organization_id BIGINT NOT NULL,suite_project_id BIGINT NOT NULL,local_project_id INT NOT NULL,module_key VARCHAR(32) NOT NULL,CHECK(singleton=1),CHECK(module_key='defects'),FOREIGN KEY(local_project_id) REFERENCES projects(id)) ENGINE=InnoDB;
CREATE TABLE suite_user_map(instance_id BIGINT NOT NULL,suite_user_id BIGINT NOT NULL,local_user_id INT NOT NULL UNIQUE,PRIMARY KEY(instance_id,suite_user_id),FOREIGN KEY(local_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE defects(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,title VARCHAR(190) NOT NULL,description TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',priority VARCHAR(20) NOT NULL DEFAULT 'normal',created_by INT NOT NULL,updated_by INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(updated_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE suite_attachments(id CHAR(64) PRIMARY KEY,defect_id INT NOT NULL,original_name VARCHAR(190) NOT NULL,mime VARCHAR(64) NOT NULL,file_size INT NOT NULL,created_by INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(defect_id) REFERENCES defects(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
